annotations-escaped.cedar:
@id("golden.annotations-escaped")
@name("Quote \"and\" backslash \\ test")
@description("Line one; still one")
@builder("1")
forbid (principal, action == Action::"read_path", resource)
when { resource.path like "*\"quoted\"*" };

classification-at-least.cedar:
@id("golden.classification-at-least")
@builder("1")
forbid (principal, action in [Action::"use_remote_embeddings", Action::"use_reranker"], resource)
when { context.workspace has classification_rank && context.workspace.classification_rank >= 300 };

classification-is.cedar:
@id("golden.classification-is")
@builder("1")
forbid (principal, action == Action::"read_connector", resource)
when { context.workspace has classification && ["confidential", "restricted"].contains(context.workspace.classification) };

command-blocks.cedar:
@id("golden.command-blocks")
@builder("1")
forbid (principal, action == Action::"run_command", resource)
when { ["kubectl"].contains(resource.program) && resource.prefixes.containsAny(["kubectl delete"]) && resource.arguments.containsAll(["rollout", "restart"]) && resource.argument_values.containsAny(["--namespace=prod"]) && ["Bash"].contains(context.tool) }
unless { resource.argument_values.containsAny(["--context=<non-prod context>"]) };

connections.cedar:
@id("golden.connections")
@builder("1")
forbid (principal, action == Action::"write_connector", resource)
when { resource in [ConnectorFamily::"servicenow"] && context.connections.containsAny(["c-1", "default"]) };

content-block-seat-route.cedar:
@id("golden.content-block-seat-route")
@builder("1")
forbid (principal, action == Action::"call_model", resource)
when { context.route == "seat" && context.content.detected.containsAny(["secrets"]) };

content-mask-except-approved.cedar:
@id("golden.content-mask-except-approved")
@builder("1")
@obligation("mask")
@mask("email,phone,iban")
@mask_style("type_token")
forbid (principal, action == Action::"call_model", resource)
when { context.content.detected.containsAny(["email", "phone", "iban"]) }
unless { resource.approved_for.containsAll(["pii"]) || (principal is User && principal.platform_admin) };

content-mask-reroute-sticky.cedar:
@id("golden.content-mask-reroute-sticky")
@builder("1")
@obligation("mask_reroute")
@reroute_to("approved-model")
@mask("email,phone,iban")
@mask_style("last4")
forbid (principal, action == Action::"call_model", resource)
when { context.content.detected.containsAny(["email", "phone", "iban"]) || (context.content.scanned && !context.content.complete) || (principal is AgentSession && principal.sensitive.containsAny(["pii"])) }
unless { context.route == "governed" && resource.approved_for.containsAll(["pii"]) && !context.content.detected.containsAny(["email", "phone", "iban"]) };

content-reroute-workspace.cedar:
@id("golden.content-reroute-workspace")
@builder("1")
@obligation("reroute")
@reroute_to("approved-model")
forbid (principal, action == Action::"call_model", resource)
when { context.workspace in [Workspace::"w1"] && (context.content.detected.containsAny(["iban"]) || (principal is AgentSession && principal.sensitive.containsAny(["pii"]))) }
unless { context.route == "governed" && resource.approved_for.containsAll(["pii"]) };

exceptions-or.cedar:
@id("golden.exceptions-or")
@builder("1")
forbid (principal, action == Action::"run_command", resource)
when { ["kubectl"].contains(resource.program) }
unless { resource.argument_values.containsAny(["--context=<non-prod context>", "--dry-run=client"]) || (principal is User && principal.platform_admin) };

group-single.cedar:
@id("golden.group-single")
@builder("1")
forbid (principal in Group::"contractors", action == Action::"write_connector", resource)
when { resource in [ConnectorFamily::"jira"] };

models-except.cedar:
@id("golden.models-except")
@builder("1")
forbid (principal, action == Action::"call_model", resource)
when { context.workspace has classification_rank && context.workspace.classification_rank >= 300 }
unless { ["approved-model"].contains(resource.alias) };

path-single.cedar:
@id("golden.path-single")
@builder("1")
forbid (principal, action == Action::"write_path", resource)
when { resource.path like "*.pem" };

paths-multi-client-tools.cedar:
@id("golden.paths-multi-client-tools")
@builder("1")
forbid (principal, action in [Action::"read_path", Action::"write_path"], resource)
when { (resource.path like "*.env" || resource.path like "*/.aws/credentials") && ["Read", "Edit"].contains(context.tool) };

remote-class-below.cedar:
@id("golden.remote-class-below")
@builder("1")
forbid (principal, action == Action::"use_reranker", resource)
when { resource has data_policy_rank && resource.data_policy_rank < 300 };

roles-multi-except-admins.cedar:
@id("golden.roles-multi-except-admins")
@builder("1")
forbid (principal, action == Action::"run_command", resource)
when { (principal in Role::"sre" || principal in Role::"analyst") }
unless { (principal is User && principal.platform_admin) };

seat-conditions.cedar:
@id("golden.seat-conditions")
@builder("1")
forbid (principal, action == Action::"use_seat", resource)
when { resource.seat_mode == "allowed" && resource.requires_governed_routing };

session-profile-and-client.cedar:
@id("golden.session-profile-and-client")
@builder("1")
forbid (principal, action == Action::"call_model", resource)
when { principal is AgentSession && principal.profile == "seat" && principal is AgentSession && principal.client == "example-client" };

tools-writes-logs.cedar:
@id("golden.tools-writes-logs")
@builder("1")
forbid (principal, action in [Action::"write_connector", Action::"read_connector", Action::"call_tool"], resource)
when { resource in [Tool::"run_kubectl", Tool::"get_pod_logs"] && context.writes && context.reads_logs };

unclassified.cedar:
@id("golden.unclassified")
@builder("1")
forbid (principal, action == Action::"call_tool", resource)
when { !(context.workspace has classification) };

user-single.cedar:
@id("golden.user-single")
@builder("1")
forbid (principal in User::"u-1", action == Action::"run_command", resource);

workspaces.cedar:
@id("golden.workspaces")
@builder("1")
forbid (principal, action == Action::"use_seat", resource)
when { context.workspace in [Workspace::"ws-1", Workspace::"ws-2"] };
